267	// Codex reports cumulative total_token_usage, so we compute the delta between the last
268	// token_count at/before the offset and the last token_count after the offset.
269	func (c *CodexAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
270		var baselineUsage *tokenUsageData // last token_count at or before offset
271		var lastUsage *tokenUsageData     // last token_count after offset
272		apiCalls := 0
273		lineNum := 0
274	
275		for _, lineData := range splitJSONL(transcriptData) {
276			lineNum++
277	
278			var line rolloutLine
279			if json.Unmarshal(lineData, &line) != nil {
280				continue
281			}
282			if line.Type != "event_msg" {
283				continue
284			}
285			var evt eventMsgPayload
286			if json.Unmarshal(line.Payload, &evt) != nil {
287				continue
288			}
289			if evt.Type != "token_count" || len(evt.Info) == 0 {
290				continue
291			}
292			var info tokenCountInfo
293			if json.Unmarshal(evt.Info, &info) != nil || info.TotalTokenUsage == nil {
294				continue
295			}
296	
297			if lineNum <= fromOffset {
298				baselineUsage = info.TotalTokenUsage
299			} else {
300				lastUsage = info.TotalTokenUsage
301				apiCalls++
302			}
303		}
304	
305		if lastUsage == nil {
306			return nil, nil //nolint:nilnil // no usage data found
307		}
308	
309		// Subtract baseline to get the delta for this checkpoint range
310		inputTokens := lastUsage.InputTokens
311		cacheReadTokens := lastUsage.CachedInputTokens
312		outputTokens := lastUsage.OutputTokens
313		if baselineUsage != nil {
314			inputTokens -= baselineUsage.InputTokens
315			cacheReadTokens -= baselineUsage.CachedInputTokens
316			outputTokens -= baselineUsage.OutputTokens
317		}
318	
319		freshInputTokens := inputTokens - cacheReadTokens
320		if freshInputTokens < 0 {
321			freshInputTokens = 0
322		}
323	
324		return &agent.TokenUsage{
325			InputTokens:     freshInputTokens,
326			CacheReadTokens: cacheReadTokens,
327			OutputTokens:    outputTokens,
328			APICallCount:    apiCalls,
329		}, nil
330	}
